from functools import wraps
import logging

LOG_LEVEL = "INFO"  

def log_request(func):
    @wraps(func)
    def wrapper(request, *args, **kwargs):
        logging.log(logging.DEBUG, f"Request: {request.method} {request.path} - Headers: {request.headers} - Body: {request.body}")
        response = func(request, *args, **kwargs)
        return response
    return wrapper

def log_response(func):
    @wraps(func)
    def wrapper(request, response, *args, **kwargs):
        logging.log(logging.DEBUG, f"Response: {response.status_code} - Body: {response.body}")
        return func(request, response, *args, **kwargs)
    return wrapper

def set_log_level(level):
    global LOG_LEVEL
    LOG_LEVEL = level

# Example usage
@log_request
@log_response
def my_view(request):
    # ... process request ...
    return response



