import unittest

from app import log_request, log_response, set_log_level, my_view

class TestLogging(unittest.TestCase):

    def setUp(self):
        set_log_level("INFO")  

    def test_log_level_filtering(self):
        # Test INFO level logging
        with self.assertLogs() as captured:
            my_view(None)  
        self.assertIn("INFO", [record.levelname for record in captured.records])

    def test_json_format(self):
        # Test JSON log format
        set_log_level("DEBUG")
        with self.assertLogs() as captured:
            my_view(None)
        for record in captured.records:
            self.assertTrue(isinstance(record.msg, str)) 

    def test_info_level_request_logging(self):
        # Test INFO level request logging
        with self.assertLogs() as captured:
            my_view(None)
        self.assertIn("INFO", [record.levelname for record in captured.records])
        self.assertIn("Request", [record.getMessage() for record in captured.records])   



